   170	        try (Connection connection = dataSource.getConnection();
   171	                PreparedStatement insert = connection.prepareStatement(
   172	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id")) {
   173	            insert.setString(1, channel);
   174	            insert.setString(2, to);
   175	            insert.setString(3, subject);
   176	            insert.setString(4, body);
   177	            insert.setString(5, status.name());
   178	            try (ResultSet generated = insert.executeQuery()) {
   179	                generated.next();
   180	                return new Message(generated.getLong("id"), channel, to, subject, body, status);
   181	            }
   182	        } catch (SQLException failure) {
   183	            throw new IllegalStateException("could not keep the message to " + to, failure);
   184	        }
